-- Other tables created below (empty)
CREATE TABLE IF NOT EXISTS murid (id INT AUTO_INCREMENT PRIMARY KEY, nama VARCHAR(200) NOT NULL, instagram VARCHAR(150) DEFAULT NULL, foto VARCHAR(255) DEFAULT NULL, status ENUM('aktif', 'non_aktif') NOT NULL DEFAULT 'aktif', created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS lagu (id_lagu INT AUTO_INCREMENT PRIMARY KEY, judul VARCHAR(255) NOT NULL, youtube_link VARCHAR(255) DEFAULT NULL, iringan_link VARCHAR(255) DEFAULT NULL, tingkat ENUM('mudah','sedang','sulit','festival') DEFAULT 'mudah') ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS pertemuan (id INT AUTO_INCREMENT PRIMARY KEY, id_murid INT NOT NULL, id_lagu INT DEFAULT NULL, coach_id INT DEFAULT NULL, tanggal DATE NOT NULL, catatan TEXT, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY (id_murid) REFERENCES murid(id) ON DELETE CASCADE, FOREIGN KEY (id_lagu) REFERENCES lagu(id_lagu) ON DELETE SET NULL, FOREIGN KEY (coach_id) REFERENCES admin(id) ON DELETE SET NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS refleksi (id INT AUTO_INCREMENT PRIMARY KEY, id_murid INT NOT NULL, tahun INT NOT NULL, bulan INT NOT NULL, refleksi TEXT, rencana_perbaikan TEXT, saran TEXT, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, UNIQUE KEY unik_murid_bulan (id_murid,tahun,bulan), FOREIGN KEY (id_murid) REFERENCES murid(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS orang_tua_murid (id INT AUTO_INCREMENT PRIMARY KEY, id_orang_tua INT NOT NULL, id_murid INT NOT NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, UNIQUE KEY unik_ortu_murid (id_orang_tua, id_murid), FOREIGN KEY (id_orang_tua) REFERENCES admin(id) ON DELETE CASCADE, FOREIGN KEY (id_murid) REFERENCES murid(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS iringan_murid (id INT AUTO_INCREMENT PRIMARY KEY, id_murid INT NOT NULL, id_lagu INT DEFAULT NULL, judul_iringan VARCHAR(255) NOT NULL, kategori ENUM('latihan','lomba','lainnya') NOT NULL DEFAULT 'latihan', gdrive_link VARCHAR(500) NOT NULL, catatan VARCHAR(255) DEFAULT NULL, created_by INT DEFAULT NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, FOREIGN KEY (id_murid) REFERENCES murid(id) ON DELETE CASCADE, FOREIGN KEY (id_lagu) REFERENCES lagu(id_lagu) ON DELETE SET NULL, FOREIGN KEY (created_by) REFERENCES admin(id) ON DELETE SET NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS rencana_pertemuan (id INT AUTO_INCREMENT PRIMARY KEY, id_murid INT NOT NULL, coach_id INT DEFAULT NULL, tahun INT NOT NULL, bulan INT NOT NULL, target_pertemuan INT NOT NULL DEFAULT 4, catatan VARCHAR(255) DEFAULT NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, UNIQUE KEY unik_murid_periode (id_murid, tahun, bulan), KEY idx_rencana_periode (tahun, bulan), KEY idx_rencana_coach (coach_id), FOREIGN KEY (id_murid) REFERENCES murid(id) ON DELETE CASCADE, FOREIGN KEY (coach_id) REFERENCES admin(id) ON DELETE SET NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS activity_log (id INT AUTO_INCREMENT PRIMARY KEY, user_id INT DEFAULT NULL, user_nama VARCHAR(150) DEFAULT NULL, user_role VARCHAR(50) NOT NULL DEFAULT 'system', action VARCHAR(50) NOT NULL, tipe ENUM('info', 'success', 'warning', 'danger') NOT NULL DEFAULT 'info', deskripsi TEXT NOT NULL, ip_address VARCHAR(45) DEFAULT NULL, user_agent VARCHAR(255) DEFAULT NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, KEY idx_created_at (created_at), KEY idx_action (action), KEY idx_user_id (user_id), FOREIGN KEY (user_id) REFERENCES admin(id) ON DELETE SET NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;


